#!/usr/bin/env python3
"""STATUS.md, generated (author 2026-10-16: one source per fact; nothing hand-kept goes stale). Commissioned instruments from
CANON/commissioning.json; every instrument's stage and next step from CANON/catalogue.json and the manifest; recent results from
CANON/results_register.json; the order of work is Biological_Physics/MethylPhys/COMMISSIONING_PLAN.md. The hand-kept STATUS up to 2026-10-15 is frozen in
Biological_Physics/MethylPhys/archive/history_2026-10-16/. Usage: python3 CANON/status_md.py [--check]"""
import os, sys, json, datetime
H = os.path.dirname(os.path.abspath(__file__)); R = os.path.dirname(H); sys.path.insert(0, H); import catalogue as CAT
OUT = os.path.join(R, "Biological_Physics/MethylPhys/STATUS.md")
J = lambda p: json.load(open(os.path.join(R, p), encoding="utf-8"))
M = {r["id"]: r for r in J("CANON/manifest.json")["rows"]}; C = J("CANON/commissioning.json"); K = J("CANON/catalogue.json"); G = J("CANON/results_register.json")["entries"]
E = lambda t: str(t or "").replace("|", "/").replace("\n", " ")
L = ["# STATUS: MethylPhys instruments, what is commissioned, what is in development, what is next", "",
     "_Generated by `CANON/status_md.py` from the commissioning record, the instrument catalogue, the results register and the Master Testing Manifest; "
     "do not edit by hand. The order of work is [Biological_Physics/MethylPhys/COMMISSIONING_PLAN.md](../../Biological_Physics/MethylPhys/COMMISSIONING_PLAN.md). The hand-kept STATUS up to 2026-10-15 is kept, frozen, in "
     "[archive/history_2026-10-16/](archive/history_2026-10-16/STATUS_to_2026-10-15.md)._", "",
     "## Commissioned", "", "**Commissioned:** " + "; ".join(i["summary"] for i in C["instruments"] if i.get("summary")) + ". Every other instrument and scope is development.", "",
     "| Instrument | Status | Scope |", "|---|---|---|"] + [i["status_line"] for i in C["instruments"] if i.get("status_line")]
L += ["", "## Every instrument", "", "| Instrument | Where it stands | Next |", "|---|---|---|"]
L += [f"| **{E(i['name'])}** | {E(CAT.stage(i, M))} | {E(i['next'])} |" for i in K["instruments"]]
L += ["", "## Results in the last 14 days (results register)", "", "| Date | Result | Status | Record |", "|---|---|---|---|"]
cut = (datetime.date.fromisoformat(max(e["date"] for e in G)) - datetime.timedelta(days=14)).isoformat()
L += [f"| {e['date']} | {E(e.get('title'))} | {E(e.get('status'))} | [{os.path.basename(e['record'])}]({os.path.relpath(os.path.join(R, e['record']), os.path.dirname(OUT))}) |"
      for e in sorted(G, key=lambda e: e["date"], reverse=True) if e["date"] >= cut and e.get("status") != "withdrawn"]
txt = "\n".join(L) + "\n"
if "--check" in sys.argv:
    ok = os.path.exists(OUT) and open(OUT, encoding="utf-8").read() == txt
    print("status_md: " + ("ok" if ok else "REFUSED: STATUS.md differs (run python3 CANON/status_md.py)")); sys.exit(0 if ok else 1)
open(OUT, "w", encoding="utf-8").write(txt); print("status_md: wrote STATUS.md")
